from hypothesis import strategies as st

@st.composite
def gen(draw):
    choice = draw(st.integers(0, 3))
    if choice == 0:
        # small ranges starting at 1, including the sample from the statement
        r = draw(st.integers(1, 200))
        l = 1
    elif choice == 1:
        # single-element ranges at edges
        l = draw(st.sampled_from([1, 9, 10, 99, 100, 999, 1000]))
        r = l
    elif choice == 2:
        # ranges around powers of ten, where zeros appear in digits
        base = draw(st.sampled_from([10, 100, 1000]))
        l = draw(st.integers(max(1, base - 30), base + 30))
        r = draw(st.integers(l, l + 60))
    else:
        l = draw(st.integers(1, 2000))
        r = draw(st.integers(l, min(l + 500, 3000)))
    return f"{l}\n{r}\n"

def validate(inp):
